tool.command:

  ln -f -s ${input_crd_path} ${input_crd_path}_`echo $$`.${input_crd_path.ext};

  ln -f -s ${input_top_path} ${input_top_path}_`echo $$`.${input_top_path.ext};

#if $config.sele == "option1":
    ln -s -f ${config.properties} ${config.properties}_`echo $$`.${config.properties.ext};
  #end if

acpype_convert_amber_to_gmx

#if $config.sele == "option1":
    --config ${config.properties}_`echo $$`.${config.properties.ext}
  #else if $config.sele == "option2":
    --config '${config.jsonstr}'
  #else if $config.sele == "option3":
    --config '__oc____dq__properties__dq__:__oc____dq__basename__dq__:__dq__${properties.basename}__dq__,__dq__binary_path__dq__:__dq__${properties.binary_path}__dq____cc____cc__'
  #end if

  #if str($input_crd_path) != 'None':
    --input_crd_path ${input_crd_path}_`echo $$`.${input_crd_path.ext}
  #end if

  #if str($input_top_path) != 'None':
    --input_top_path ${input_top_path}_`echo $$`.${input_top_path.ext}
  #end if


  --output_path_gro $outname_output_path_gro

  --output_path_top $outname_output_path_top
;
#if $config.sele == "option1":
    rm -f ${config.properties}_`echo $$`.${config.properties.ext};
  #end if

  rm -f ${input_crd_path}_`echo $$`.${input_crd_path.ext};

  rm -f ${input_top_path}_`echo $$`.${input_top_path.ext};


  if test -f $outname_output_path_gro; then mv $outname_output_path_gro $output_path_gro; fi;

  if test -f $outname_output_path_top; then mv $outname_output_path_top $output_path_top; fi;
